import {describeMove,STATUS} from './combat-rules.mjs';
export function showCombatInfo(b){const g=b.g,t=b.visual.teams.find(t=>t.pid===b.me().pid)||b.me(),m=t.mons[t.active],names={atk:'Attaque',def:'Défense',spa:'Atq. Spé.',spd:'Déf. Spé.',speed:'Vitesse',accuracy:'Précision',evasion:'Esquive'};g.openModal(`<div class="combat-info"><span class="eyebrow">ÉTAT DU COMBAT · TOUR ${b.visual.turn}</span><h2>${m.name}</h2><p>${m.ability} · ${STATUS[m.status]||'Aucun statut majeur'} · ${m.hp}/${m.max} PV</p><div class="combat-stage-list">${Object.entries(names).map(([key,name])=>`<span>${name}<b>${(m.stages?.[key]||0)>0?'+':''}${m.stages?.[key]||0}</b></span>`).join('')}</div><h3>Ses quatre capacités</h3>${m.moves.map(move=>`<article><b>${move.name} <small>${move.left}/${move.pp} PP</small></b><p>${g.escape(describeMove(move))}</p></article>`).join('')}<p class="muted">Les variations vont de −6 à +6 et disparaissent au changement de Pokémon. Les statuts majeurs persistent. Les priorités passent avant la Vitesse.</p><button class="primary" data-act="close-modal">Retour au combat</button></div>`,{className:'combat-info-dialog'})}
